// docs/format is generated from vellum-types (guide Prompt 8): the JSON Schema of the .vellum document and
// a reference page written from it. Both are regenerated by scripts/gen-format.mjs, never hand-edited, and
// they must never drift from the Rust types.
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { appendFileSync, cpSync, existsSync, rmSync } from "node:fs";
import { test } from "node:test";
import { renderFilesSpec, renderFormatSpec } from "../lib/format-spec.mjs";
import { at, discard, read, repo, scratch } from "./helpers.mjs";

const script = at("scripts", "gen-format.mjs");
const committed = at("docs", "format");

const check = (target) =>
  spawnSync("node", [script, "--check", "--target", target], { cwd: repo, encoding: "utf8" });

const demo = {
  title: "Demo",
  description: "A demo document.",
  type: "object",
  required: ["meta"],
  properties: {
    meta: { $ref: "#/$defs/Meta" },
    pages: { type: "array", items: { $ref: "#/$defs/Page" } },
    themes: {
      type: "object",
      additionalProperties: { type: "array", items: { type: "string" } },
    },
  },
  $defs: {
    Page: {
      type: "object",
      required: ["id"],
      properties: { id: { type: "string", description: "The page id." } },
    },
    Meta: {
      type: "object",
      description: "The meta block.",
      required: ["name"],
      properties: {
        name: { type: "string", description: "The name." },
        kind: { type: "string", enum: ["document", "library"] },
      },
    },
  },
};

test("the committed docs/format matches what vellum-types generates", () => {
  const out = check(committed);
  assert.equal(out.status, 0, out.stdout + out.stderr);
});

test("a hand-edited schema is detected", () => {
  const tmp = scratch("format-spec");
  try {
    cpSync(committed, tmp, { recursive: true });
    appendFileSync(`${tmp}/vellum.schema.json`, "\n");
    const out = check(tmp);
    assert.equal(out.status, 1, out.stdout + out.stderr);
    assert.match(out.stderr, /vellum\.schema\.json/);
  } finally {
    discard(tmp);
  }
});

test("the committed reference page is the one the generator writes", () => {
  assert.ok(existsSync(at("docs", "format", "README.md")), "docs/format/README.md is missing");
  assert.match(read("docs", "format", "README.md"), /Generated from `crates\/vellum-types`/);
});

test("the reference page lists each property with its type and whether it is required", () => {
  const page = renderFormatSpec(demo);
  assert.match(page, /^# /m);
  assert.match(page, /A demo document\./);
  assert.match(page, /\| `meta` \| \[Meta\]\(#meta\) \| yes \|/);
  assert.match(page, /\| `pages` \| array of \[Page\]\(#page\) \| no \|/);
  assert.match(page, /\| `themes` \| map from string to array of string \| no \|/);
});

test("a definition has its own section with its description and fields", () => {
  const page = renderFormatSpec(demo);
  assert.match(page, /^### Meta$/m);
  assert.match(page, /The meta block\./);
  assert.match(page, /\| `name` \| string \| yes \| The name\. \|/);
  assert.match(page, /\| `kind` \| one of "document", "library" \| no \|/);
  assert.match(page, /^### Page$/m);
});

test("the page is deterministic and ends with one newline", () => {
  const once = renderFormatSpec(demo);
  assert.equal(renderFormatSpec(demo), once);
  assert.ok(once.endsWith("\n") && !once.endsWith("\n\n"), "one trailing newline");
});

test("a union describes each of its variants", () => {
  const page = renderFormatSpec({
    ...demo,
    $defs: {
      ...demo.$defs,
      Override: {
        description: "What an override does.",
        oneOf: [
          {
            type: "object",
            required: ["props"],
            properties: { props: { type: "object" } },
          },
          {
            type: "object",
            required: ["children"],
            properties: { children: { type: "array", items: { $ref: "#/$defs/Page" } } },
          },
        ],
      },
    },
  });
  assert.match(page, /^### Override$/m);
  assert.match(page, /- `props`: object/);
  assert.match(page, /- `children`: array of \[Page\]\(#page\)/);
});

// --- On disk (guide Prompt 24): files.md is written from what the real codecs produce ---

const files = {
  formatVersion: 3,
  migrations: [
    { from: 1, to: 2 },
    { from: 2, to: 3 },
  ],
  thresholds: { nodes: 10000, bytes: 4000000 },
  single: '{\n  "meta": {}\n}\n',
  directory: {
    "index.json": '{\n  "index": true\n}\n',
    "pages/page00001.json": '{\n  "page": 1\n}\n',
  },
  assets: {
    folder: "app.assets",
    file: "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad",
  },
};

test("the committed docs/format has the on-disk page and the reference links to it", () => {
  assert.ok(existsSync(at("docs", "format", "files.md")), "docs/format/files.md is missing");
  assert.match(read("docs", "format", "files.md"), /Generated from `crates\/vellum-types`/);
  assert.match(read("docs", "format", "README.md"), /\[files\.md\]\(files\.md\)/);
});

test("a missing on-disk page is detected", () => {
  const tmp = scratch("format-spec-files");
  try {
    cpSync(committed, tmp, { recursive: true });
    rmSync(`${tmp}/files.md`);
    const out = check(tmp);
    assert.equal(out.status, 1, out.stdout + out.stderr);
    assert.match(out.stderr, /files\.md/);
  } finally {
    discard(tmp);
  }
});

test("the on-disk page describes every place a document keeps something", () => {
  const page = renderFilesSpec(files);
  for (const heading of [
    "Files on disk",
    "Assets",
    "Custom fonts",
    "Libraries",
    "Directory format",
    "Large files",
    "Examples",
    "Migrations",
  ]) {
    assert.match(page, new RegExp(`^#{2,3} ${heading}$`, "m"), `no section: ${heading}`);
  }
  assert.match(page, /app\.assets\/ba7816bf/);
  assert.match(page, /\.lib\.vellum/);
  assert.match(page, /~\/\.vellum\/cache/);
});

test("the examples are the files the codecs wrote, verbatim", () => {
  const page = renderFilesSpec(files);
  assert.ok(page.includes(files.single.trimEnd()), "the single file");
  for (const [name, text] of Object.entries(files.directory)) {
    assert.ok(page.includes(`### \`app.vellum/${name}\``), `no heading for ${name}`);
    assert.ok(page.includes(text.trimEnd()), name);
  }
});

test("the migration notes list each step and say what a newer file does", () => {
  const page = renderFilesSpec(files);
  assert.match(page, /format version is 3/i);
  assert.match(page, /\| 1 \| 2 \|/);
  assert.match(page, /\| 2 \| 3 \|/);
  assert.match(page, /newer version/i);
  assert.match(page, /read-only|not read/i);

  const none = renderFilesSpec({ ...files, formatVersion: 1, migrations: [] });
  assert.match(none, /no migrations yet/i);
});

test("the thresholds come from the numbers the engine uses", () => {
  const page = renderFilesSpec({ ...files, thresholds: { nodes: 123, bytes: 456 } });
  assert.match(page, /123 nodes/);
  assert.match(page, /456 bytes/);
});

test("the on-disk page is deterministic and ends with one newline", () => {
  const once = renderFilesSpec(files);
  assert.equal(renderFilesSpec(files), once);
  assert.ok(once.endsWith("\n") && !once.endsWith("\n\n"));
});
